/* Disposable round-3 design fixtures. No app boot, mutations or persistence. */
const query=new URLSearchParams(location.search);
const lang=query.get('lang')||'pt', theme=query.get('theme')||'light';
const screen=query.get('screen')||'today', stage=query.get('stage')||'mid';
const words=(en,pt)=>lang==='pt'?pt:en;
const finishEvent=query.get('event')||'calibrated';
const finishEvents={solid:{before:149,after:160,label:2,body:words('Your comparable sets now support Solid standing.','Suas séries comparáveis agora sustentam uma base bem fundamentada.')},checked:{before:157,after:168,label:3,body:words('First test set saved: guessed 11, did 11.','Primeira série-teste salva: estimou 11, fez 11.')},calibrated:{before:157,after:168,label:4,body:words('Third check saved: guessed 12, did 12. Your checks agree.','Terceira série-teste salva: estimou 12, fez 12. Suas séries-teste concordam.')}};
const finishCase=finishEvents[finishEvent]||finishEvents.calibrated;
const title=words('Your profile','Seu perfil');
const names=[words('Machine chest press','Supino na máquina'),words('Lat pulldown','Puxada alta'),words('Cable row','Remada no cabo'),'Leg press'];
const states={fresh:{steps:0,observations:0,transitions:0,sessions:0},mid:{steps:157,observations:60,transitions:14,sessions:15},full:{steps:272,observations:192,transitions:16,sessions:48}};
const state=screen==='today'?states[stage]:states.mid;
const labels=[words('First time','Primeira vez'),words('Learning','Aprendendo'),words('Solid','Bem fundamentada'),words('Checked by a test set','Com série-teste'),words('Well calibrated','Bem calibrado')];
document.documentElement.lang=lang==='pt'?'pt-BR':'en';
document.documentElement.dataset.theme=theme;
document.body.classList.toggle('capture',query.has('capture'));
function href(next,nextStage=stage){const q=new URLSearchParams(location.search);q.set('screen',next);q.set('stage',nextStage);q.delete('freeze');return `?${q}`;}
function status(){return '<div class="statusbar" aria-hidden="true"><span>9:41</span><span>▰ ▰ ▰</span></div>';}
function ring(steps,budget=320,large=false){return `<svg class="ring${large?' large':''}" viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="27" pathLength="100"/><circle class="filled${steps===0?' empty':''}" cx="32" cy="32" r="27" pathLength="100" data-fill="${steps/budget*100}"/></svg>`;}
function head(text,right=''){return `<header class="pagehead"><div><h1>${text}</h1>${screen==='today'?`<p class="meta">${words('Wednesday, November 11','Quarta-feira, 11 de novembro')}</p>`:''}</div>${right}</header>`;}
function dock(active){return `<nav class="dock" aria-label="${words('Sections','Seções')}">${[['today','log',words('Today','Hoje')],['overview','stats',words('Progress','Progresso')],['history','history',words('History','Histórico')],['program','program',words('Program','Treino')]].map(([id,icon,label])=>`<a href="${href(id==='today'?'today':'overview')}" ${id===active?'class="active" aria-current="page"':''}><span class="nav__icon" data-i="${icon}" aria-hidden="true"></span>${label}</a>`).join('')}</nav>`;}
function profileReading(steps=state.steps){return `<div class="profile-reading">${ring(steps,320,true)}<div><p class="reading-title">${words('Built from your saved sessions','Construído com suas sessões salvas')}</p><p class="hint">${words('4 lifts · 15 comparable sessions','4 exercícios · 15 sessões comparáveis')}</p><p class="caption">${words('No evidence is lost during rest.','As pausas não apagam o que já foi aprendido.')}</p></div></div>`;}
function today(){
 const next=stage==='fresh'?words('Your first saved sets start your profile.','Suas primeiras séries salvas começam seu perfil.'):stage==='full'?words('Well calibrated. Your record keeps growing.','Bem calibrado. Seu histórico continua crescendo.'):words('Cable row: one more test set to understand the pattern.','Remada: mais uma série-teste para entender o padrão.');
 return `${status()}<main>${head(words('Today','Hoje'),`<a class="ring-link" href="${href('overview')}" aria-label="${title}. ${words('Open saved evidence','Abrir evidências salvas')}">${ring(state.steps)}<span>${title}</span></a>`)}<p class="eyebrow">${words('Your program','Seu treino')}</p><p class="program-name">${words('Full body','Corpo inteiro')}</p><p class="meta">${words('Day A · 4 exercises · 12 sets','Dia A · 4 exercícios · 12 séries')}</p><p class="next-evidence">${next}</p><section class="training"><h2>${words('This session','Esta sessão')}</h2>${names.map((name,i)=>`<div class="rxrow"><div class="rxrow__name">${name}<span class="rxrow__sub">3 × 8–12</span></div><span class="rxrow__load">${stage==='fresh'?'—':[40,40,35,100][i]} kg</span><span class="rxrow__target">${stage==='fresh'?'—':'10'} reps</span></div>`).join('')}<a class="btn btn--cta" href="${href('finish','mid')}">${words('Start session','Começar sessão')}</a></section><p class="caption">${words('Prototype · synthetic saved evidence','Protótipo · evidências salvas fictícias')}</p></main>${dock('today')}`;
}
function finding(finished=false){return `<section class="profile-finding"><p class="eyebrow">${words('From your record','Do seu histórico')}</p><p>${finished?words('Your cable-row test sets now agree with your estimates.','Suas séries-teste de remada agora concordam com suas estimativas.'):words('Your first cable-row test set: you guessed 11 and did 11.','Sua primeira série-teste de remada: você estimou 11 e fez 11.')}</p><p class="caption">${finished?words('The first two checks changed no bias.','As duas primeiras séries-teste não mudaram a correção.'):words('Next: 1 more valid check before a pattern can be established.','A seguir: mais 1 série-teste válida antes de estabelecer um padrão.')}</p></section>`;}
function overview(){
 return `${status()}<main class="overview-main">${head(words('Progress','Progresso'))}<div class="tabrow"><span>${words('Overview','Visão geral')}</span><span>${words('Strength','Força')}</span><span>${words('Review','Revisão')}</span><span>${words('Volume','Volume')}</span></div><h2 class="profile-heading">${title}</h2><p class="hint intro">${words('What Taurifer knows about you','O que o Taurifer sabe sobre você')}</p>${profileReading()}<div class="detail-counts"><span>${words('60 lift observations','60 registros por exercício')}</span><span>${words('14 stage transitions','14 etapas alcançadas')}</span></div><ul class="profile-lifts">${names.map((name,i)=>`<li class="profile-lift"><a href="${href('lift')}"><div><h3>${name}</h3><p>${i<2?labels[4]:labels[3]}</p></div><span class="caption">${words('15 saved sessions','15 sessões salvas')}<span class="chevron" aria-hidden="true"></span></span></a></li>`).join('')}</ul><p class="hint">${words('Two lifts have agreeing checks. Two are still being checked.','Dois exercícios têm séries-teste que concordam. Dois ainda estão sendo verificados.')}</p>${finding()}</main>${dock('overview')}`;
}
function lift(){
 const needs=[words('Before the first saved session.','Antes da primeira sessão salva.'),words('Saved load and comparable sets.','Carga e séries comparáveis salvas.'),words('Standing reached Solid on Jan 16.','Base bem fundamentada em 16 jan.'),words('2 checks: guessed 11, did 11; guessed 10, did 11.','2 séries-teste: estimou 11, fez 11; estimou 10, fez 11.'),words('Next: 1 more valid check. Spread at most 1.25 reps and bias below 0.75 reps.','A seguir: mais 1 série-teste válida. Dispersão de até 1,25 reps e viés abaixo de 0,75 rep.')];
 return `${status()}<main class="lift-main"><a class="back" href="${href('overview')}">${words('Back to your profile','Voltar ao seu perfil')}</a><h1>${names[2]}</h1><p class="meta">${words('Your profile · this lift','Seu perfil · este exercício')}</p><div class="lift-status"><h2>${labels[3]}</h2><p>${words('Current estimate: Solid','Estimativa atual: bem fundamentada')}</p></div><ol class="stage-list">${labels.map((label,i)=>`<li class="${i<4?'reached':'pending'}"><span class="stage-mark" aria-hidden="true">${i<4?'✓':'5'}</span><div><h3>${label}</h3><p>${needs[i]}</p></div></li>`).join('')}</ol><div class="depth"><h2>${words('The record keeps growing','O histórico continua crescendo')}</h2><p>${words('15 of 64 comparable-session dates saved. Each later date adds evidence within this stage.','15 de 64 datas com sessões comparáveis salvas. Cada nova data amplia a base nesta etapa.')}</p><p class="caption">${words('Test sets stay optional. At 32 dates, Long record is another route. At 64, Established from history.','Séries-teste são opcionais. Com 32 datas, Histórico amplo é outro caminho. Com 64, Base consolidada pelo histórico.')}</p></div></main>${dock('overview')}`;
}
function finish(){return `${status()}<main class="finish-main"><p class="eyebrow">${words('Session saved','Sessão salva')}</p><h1>${words('Day A','Dia A')}</h1><p class="meta">${words('Full body · November 11','Corpo inteiro · 11 de novembro')}</p><div class="totals"><div><b>12</b><small>${words('sets','séries')}</small></div><div><b>4</b><small>${words('exercises','exercícios')}</small></div><div><b>42 min</b><small>${words('duration','duração')}</small></div></div><section class="finish-profile"><h2>${title}</h2>${profileReading(finishCase.before)}<h3>${names[2]} · ${labels[finishCase.label]}</h3><p>${finishCase.body}</p><p class="hint">${words('Four lift observations and one stage added to your profile.','Quatro registros por exercício e uma etapa acrescentados ao seu perfil.')}</p><a class="text-link" href="${href('lift')}">${words('See this lift’s stages','Ver as etapas deste exercício')}</a></section>${finishEvent==='calibrated'?finding(true):''}<section class="finish-lift"><h3>${names[2]}</h3><p class="values">35 kg × 11 · 10 · 12</p><p class="caption">${finishEvent==='calibrated'?words('Current standing: Solid · spread 0.58 reps','Base atual: bem fundamentada · dispersão 0,58 reps'):words('Current standing: Solid','Base atual: bem fundamentada')}</p></section></main><footer class="finish-actions"><a class="btn btn--cta" href="${href('today','mid')}">${words('Done','Concluir')}</a></footer>`;}
function scope(){return `${status()}<main class="scope-main"><a class="back" href="${href('overview')}">${words('Your profile','Seu perfil')}</a><h1>${words('More lifts to learn','Mais exercícios para conhecer')}</h1><p class="meta">${words('New program · end of week 8','Novo treino · fim da semana 8')}</p><div class="scope-rings"><div>${ring(200,320)}<p>${words('4 lifts, before','4 exercícios, antes')}</p></div><div>${ring(200,480,true)}<p>${words('6 lifts, now','6 exercícios, agora')}</p></div></div><h2>${words('All saved evidence retained','Todas as evidências mantidas')}</h2><p class="caption">${words('96 lift observations · 16 attained stages','96 registros por exercício · 16 etapas alcançadas')}</p><p>${words('Your new program keeps four comparable lifts and adds two. Your profile now includes their learning too.','Seu novo treino mantém quatro exercícios comparáveis e acrescenta dois. Seu perfil agora inclui o aprendizado deles também.')}</p><ul class="scope-list"><li><b>${words('4 continuing lifts','4 exercícios mantidos')}</b><p>${words('Their stages, checks and saved sessions carry over.','Etapas, séries-teste e sessões salvas continuam valendo.')}</p></li><li><b>${words('2 new lifts','2 exercícios novos')}</b><p>${words('First time. They start with their first saved sets.','Primeira vez. Começam com suas primeiras séries salvas.')}</p></li></ul><p class="caption">${words('A larger scope changes the ring’s scale. No earned evidence was removed. Rest never reduces it.','Mais exercícios mudam a escala do anel. Nenhuma evidência foi removida. As pausas nunca a reduzem.')}</p><a class="btn btn--cta" href="${href('overview')}">${words('See your profile','Ver seu perfil')}</a></main>`;}
function paint(){document.querySelector('#phone').innerHTML=screen==='overview'?overview():screen==='lift'?lift():screen==='finish'?finish():screen==='scope'?scope():today();requestAnimationFrame(()=>document.querySelectorAll('.filled').forEach(el=>el.style.strokeDasharray=`${el.dataset.fill} 100`));}
function afterSave(){document.querySelector('.filled').style.strokeDasharray=`${finishCase.after/320*100} 100`;document.querySelector('.profile-reading .hint').textContent=words('4 lifts · 16 comparable sessions','4 exercícios · 16 sessões comparáveis');document.querySelector('#phone').dataset.saved='after';}
window.replaySavedChange=()=>{paint();document.querySelector('#phone').dataset.saved='before';requestAnimationFrame(()=>requestAnimationFrame(afterSave));};
paint();if(screen==='finish'&&query.get('freeze')!=='before')requestAnimationFrame(()=>requestAnimationFrame(afterSave));
for(const key of ['screen','stage','lang','theme']){document.getElementById(key).value={screen,stage,lang,theme}[key];document.getElementById(key).onchange=event=>{const q=new URLSearchParams(location.search);q.set(key,event.target.value);q.delete('freeze');location.search=q;};}
document.querySelector('#replay').disabled=screen!=='finish';document.querySelector('#replay').onclick=window.replaySavedChange;
document.querySelector('#fixture').textContent=`DISPOSABLE / ${screen==='finish'?`${finishCase.before}→${finishCase.after} / four lift-dates × 0.75 + one stage × 8`:screen==='scope'?'200/320 → 200/480 / 4 retained + 2 new':`${state.steps}/320 / ${state.observations} lift-dates + ${state.transitions} transitions`} / no storage or app runtime`;

document.querySelector('#event').value=finishEvent;document.querySelector('#event').onchange=event=>{const q=new URLSearchParams(location.search);q.set('event',event.target.value);location.search=q;};
